mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const titles=arr(input.sheets).map(s=>String(((s||{}).properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(const off of [0,-1]){ const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+off,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t); }
const q=s=>"'"+s+"'";
const filters=tabs.length? tabs.map(t=>({a1Range:q(t)+'!A1:H2000'})) : [{a1Range:q('הגדרות')+'!A1:A1'}];
return {tabs: tabs.join(', '), readBody: JSON.stringify({dataFilters:filters, valueRenderOption:'FORMATTED_VALUE'})};

const f=Array.isArray(input.files)?input.files:[];
const fid=f[0]&&f[0].id?f[0].id:'';
const q=s=>"'"+s+"'";
const names=['אקטיבציות פרימיום-ללא עיסקיים','אקטיבציות דיסקאונט-ללא עיסקיים','אקטיבציות ISP ONLY-ללא עיסקיים '];
return {fid, fname:(f[0]||{}).name||'', readBody: JSON.stringify({dataFilters:names.map(n=>({a1Range:q(n)+'!A1:AZ4000'})), valueRenderOption:'FORMATTED_VALUE'})};

const digits=s=>String(s==null?'':s).replace(/\D/g,'');
const norm=s=>String(s==null?'':s).replace(/\s+/g,' ').trim();
const arr=v=>{ if(typeof v==='string'){ try{return JSON.parse(v);}catch(e){return [];} } return Array.isArray(v)?v:[]; };
const text=norm(input.text);
const existing=norm(input.rating);
const phone=digits(input.phone);
const MANAGERS=['972544604246','972504445169'];
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const pad=n=>('0'+n).slice(-2);
const stamp=nowIL.getFullYear()+'-'+pad(nowIL.getMonth()+1)+'-'+pad(nowIL.getDate())+' '+pad(nowIL.getHours())+':'+pad(nowIL.getMinutes());
const dispDate=pad(nowIL.getDate())+'/'+pad(nowIL.getMonth()+1)+'/'+nowIL.getFullYear()+' '+pad(nowIL.getHours())+':'+pad(nowIL.getMinutes());
let inWindow=true;
const m0=norm(input.sentAt).match(/(\d{4})-(\d{2})-(\d{2})/);
if(m0){const sent=new Date(+m0[1],+m0[2]-1,+m0[3]); inWindow=(nowIL-sent)/86400000<=8;}
const greet=/^(היי|הי|שלום|אהלן|הלו|תודה|תודה רבה|תודה לך|ok|אוקי|אוקיי|כן|בסדר|👍|🙏|❤️|😊)[\s!.,?🙏😊👍❤️]*$/i;
const cellular=/(קווים|קוים|קו |סלולר|פרטנר|סלקום|הוט|פלאפון|גולן|סים|מנוי)/;
const refuse=/(הסר|תסיר|תפסיקו|לא מעוני|לא תודה|אין צורך|לא רלוונטי)/;
const cellWide=/(קווים|קוים|קווי|קו |סלולר|פרטנר|סלקום|הוט|פלאפון|גולן|סים|מנוי|מכשירים|טלפונים|ניידים|רמי לוי|019|012|018|וואלה|we4g)/i;
const cellWant=t=>!!t && cellWide.test(t) && !/פלאפון/.test(t) && !refuse.test(t);
// RULE (Steve 15/11/2026): a short clearly-positive reply with no complaint ("הכל מצוין", "מרוצים") counts like a high rating: no rep message, no "העברנו לנציג" reply. Do not remove.
const isPos=t=>{t=String(t||'');return t.length<=80&&/(מצוין|מצויין|מעולה|מעולים|הכל טוב|הכול טוב|הכל בסדר|הכול בסדר|מרוצה|מרוצים|סבבה|אחלה|תותח|מדהים|נהדר|טוב מאוד|טוב מאד|הכל עובד|הכול עובד|עובד טוב|עובד מצוין|שירות טוב|שירות מעולה|הכל תקין|הכול תקין)/.test(t)&&!/(אבל|רק ש|תקלה|תקוע|נתקע|קופץ|איטי|לנתק|ניתוק|חיוב|יקר|מחיר|לא עובד|לא מרוצ|לא טוב|לא בסדר|לא תקין|גרוע|מאוכזב|בעיה עם|יש בעיה|יש לי בעיה|חסר|טכנאי לא)/.test(t);};
const nameFull=norm(input.custName)||norm(input.name);
const first=nameFull.split(' ')[0];
const local='0'+phone.replace(/^972/,'');
const rep=norm(input.rep), inst=norm(input.installDate);
const repFirst=rep.split(' ')[0];
let custNum='';
{ const key=phone.slice(-9);
  if(key.length===9){ for(const vr of arr(input.sales)){ if(custNum) break; const vals=((vr&&vr.valueRange)||vr||{}).values||[];
    for(const r of vals.slice(1)){ if(!r) continue; if(digits(r[3]).slice(-9)===key){ const n=digits(r[6]); if(n.length>=6){ custNum=n; break; } } } } } }
let actDate='';
if(custNum){ for(const vr of arr(input.act)){ if(actDate) break; const vals=((vr&&vr.valueRange)||vr||{}).values||[]; let hi=-1; for(let i=0;i<Math.min(vals.length,6);i++){ if((vals[i]||[]).some(c=>String(c).includes(`מס' לקוח`))){hi=i;break;} } if(hi<0) continue; const h=vals[hi]; const ci=h.findIndex(c=>String(c).trim()===`מס' לקוח`); const di=h.findIndex(c=>String(c).includes('תאריך האקטיבציה')); if(ci<0||di<0) continue; const row=vals.slice(hi+1).find(r=>r&&String(r[ci]).trim()===custNum); if(row&&row[di]) actDate=String(row[di]).trim(); } }
const cn=custNum?'\nמספר לקוח: '+custNum:'';
const cnInline=custNum?', מספר לקוח '+custNum:'';
const block='\n\nפרטים לפנייה למשווקים:\n💙 מספר לקוח: '+(custNum||'לא נמצא')+'\n💙 מספר טלפון: '+local+'\n💙 תאריך אקטיבציה: '+(actDate||'עוד לא אוקטב – נא לברר מול YES');
const preventLine='\nעל מנת למנוע ניתוק, נא לחזור ללקוח היום, ואם צריך – לשלוח פנייה לתיבת המשווקים.';
const cellLine='\n📱 הלקוח הזכיר סלולר – לבדוק איתו גם קווים.';
let repPhone='';
{ const cand=arr(input.targets).filter(r=>r&&r[0]&&r[1]);
  let hit=cand.find(r=>norm(r[0])===rep);
  if(!hit){ const bf=cand.filter(r=>norm(r[0]).split(' ')[0]===repFirst); if(bf.length===1) hit=bf[0]; }
  if(!hit){ const sw=cand.filter(r=>norm(r[0]).startsWith(rep)||rep.startsWith(norm(r[0]))); if(sw.length===1) hit=sw[0]; }
  if(hit){ let p=digits(hit[1]); if(p.startsWith('0')) p='972'+p.slice(1); if(/^9725\d{8}$/.test(p)) repPhone=p; } }
let d=null, rest=text;
let m=text.match(/^\s*([1-5])(?!\d)\s*[-–:.,)\/]*\s*(.*)$/);
if(m && !cellular.test(norm(m[2]).slice(0,12))){d=+m[1]; rest=norm(m[2]).replace(/^(מתוך\s*5|\/\s*5)\s*[-–:.,]*\s*/,'');}
else { m=text.match(/(?:דירוג|ציון)\s*(?:של\s*)?([1-5])(?!\d)/); if(m){d=+m[1];} }
const trivial=!text||greet.test(text);
const info=(title,rating,body)=>title+'\nלקוח: '+nameFull+'\nטלפון: '+local+cn+'\nנציג: '+rep+'\nהתקנה: '+inst+(rating?'\nדירוג: '+rating+'/5':'')+(body?'\nמה הלקוח כתב: "'+body+'"':'');
const ask='היי '+first+', תודה ששיתפת 🙏 מצטערים שהחוויה לא הייתה כמו שרצינו. אפשר לכתוב לנו בקצרה מה היה לא טוב? הנציג שלך יחזור אליך אישית כדי לטפל בזה.';
const cellQ='היי '+first+', תודה על הדירוג 🙏 שאלה קצרה: באיזו חברה הסלולר שלכם היום, וכמה קווים יש? (למשל: פרטנר, 3 קווים)';
const thanks='תודה '+first+' 🙏 העברנו את זה לנציג שלך והוא יחזור אליך בהקדם כדי לטפל בזה.';
const noRep='⚠️ הנציג '+(rep||'(לא ידוע)')+' כבר לא עובד / לא נמצא לו טלפון – ההודעה מגיעה אליכם במקומו\n\n';
const res={action:'ignore',update:false,writeRow:false,sendAlert:false,sendReply:false,sendRep:false,repPhone:'',repMsg:'',custNum,actDate,rating:existing,alertedAt:norm(input.alertedAt),thankedAt:norm(input.thankedAt),alertMsg:'',reply:'',rowText:'',rowRating:'',dispDate,alertPhone:MANAGERS[0],alertPhone2:MANAGERS[1],localPhone:local,nameFull,rep,inst};
// שולח לנציג; אם הנציג לא עובד/אין טלפון – לסטיב ולירדן
const toRep=msg=>{ if(repPhone){ res.sendRep=true; res.repPhone=repPhone; res.repMsg=msg; } else { res.sendAlert=true; res.alertMsg=noRep+msg; } };
const cellTask=t=>'היי '+repFirst+', משימה: לחזור ללקוח 📞\nלקוח: '+nameFull+'\nטלפון: '+local+cn+'\nהתקנה: '+inst+(existing||d!==null?'\nדירוג: '+(existing||d)+'/5':'')+'\nהלקוח מעוניין בקווי סלולר 📱\nמה שהוא כתב: "'+t+'"\nנא לחזור אליו היום.';
// הודעת שביעות רצון בחשבונית 1/3 (מגן ניתוקים): כל תגובה עוברת לנציג שמכר
// RULE (Steve 15/11/2026): a high rating (4/5) or a short positive text, with no complaint and no cellular interest, is NOT sent to the rep and gets no "העברנו לנציג" reply. Do not remove.
if(/^bill/.test(norm(input.kind))){
  if(inWindow && phone && !(trivial&&d===null)){
    res.action='bill_reply';
    const what=(d!==null)?('דירוג: '+d+'/5'+(rest.length>=3?'\nמה שהוא כתב: "'+rest+'"':'')):('מה שהוא כתב: "'+text+'"');
    const low=(d===null||d<=3);
    const highOnly=((d!==null&&d>=4&&(rest.length<3||greet.test(rest)||isPos(rest)))||(d===null&&isPos(text)))&&!cellWant(text);
    if(highOnly){ res.action='bill_high_skip'; }
    else toRep('היי '+repFirst+', הלקוח '+nameFull+' ('+local+cnInline+') שמכרת לו, התקנה: '+inst+', ענה להודעת שביעות הרצון ששלחנו לו 💬\n'+what+(cellWant(text)?cellLine:'')+'\nנא לחזור אליו היום.'+(low?block:''));
    if(low && !highOnly && !res.thankedAt){ res.sendReply=true; res.reply=thanks; res.thankedAt=stamp; res.update=true; }
  }
  res.appendBody='';
  return res;
}
if(!inWindow||!phone||(trivial&&d===null)){
}else if(existing===''){
  if(d!==null){
    res.rating=String(d); res.update=true;
    if(d<=2){
      res.action='low'; res.writeRow=true; res.alertedAt=stamp; res.sendReply=true; res.rowText=rest; res.rowRating=String(d);
      toRep('היי '+repFirst+', הלקוח '+nameFull+' ('+local+cnInline+') שמכרת לו, התקנה: '+inst+', דירג נמוך: '+d+'/5 ⚠️\n'+(rest.length>=3?'מה שהוא כתב: "'+rest+'"':'הוא עוד לא פירט מה לא היה טוב, נעדכן אותך כשיכתוב.')+(cellWant(rest)?cellLine:'')+preventLine+block);
      if(rest.length>=3){res.thankedAt=stamp; res.reply=thanks;} else {res.reply=ask;}
    } else if(d===5||d===4){ res.action='five'; res.sendReply=true; res.reply=cellQ; }
    else { res.action='rated'; if(cellWant(rest)){ res.action='cell_any'; toRep(cellTask(rest)); } }
  } else if(cellWant(text)){
    res.action='cell_any'; toRep(cellTask(text));
  } else if(!cellular.test(text) && !isPos(text)){
    res.action='text_norating'; res.writeRow=true; res.rowText=text;
    toRep('היי '+repFirst+', הלקוח '+nameFull+' ('+local+cnInline+') שמכרת לו, התקנה: '+inst+', כתב לנו אחרי ההתקנה 💬\nמה שהוא כתב: "'+text+'"\nנא לחזור אליו היום.'+block);
  }
} else if(existing==='5'||existing==='4'){
  if(!res.alertedAt && !/(פלאפון)/.test(text) && !refuse.test(text) && (cellular.test(text)||/\d/.test(text))){
    res.action='five_answer'; res.update=true; res.alertedAt=stamp;
    toRep(cellTask(text));
  }
} else if(existing==='1'||existing==='2'){
  const written=(d!==null)?rest:text;
  if(written.length>=3 && !greet.test(written)){
    res.action='low_more'; res.writeRow=true; res.rowText=written; res.rowRating=existing;
    toRep('היי '+repFirst+', עדכון על הלקוח '+nameFull+' ('+local+cnInline+') שמכרת לו, דירג נמוך: '+existing+'/5 ⚠️\nהוא כתב: "'+written+'"'+(cellWant(written)?cellLine:'')+preventLine+block);
    if(!res.thankedAt){res.sendReply=true; res.reply=thanks; res.thankedAt=stamp; res.update=true;}
  }
} else if(existing==='3'){
  if(cellWant(text)){ res.action='cell_any'; toRep(cellTask(text)); }
}
res.appendBody=JSON.stringify({requests:[{appendCells:{sheetId:2026110101,rows:[{values:[dispDate,nameFull,local,rep,inst,res.rowRating,res.rowText,'',''].map(v=>({userEnteredValue:{stringValue:String(v)}}))}],fields:'userEnteredValue'}}]});
return res;
